package com.workworth.earnings.application;
import com.workworth.earnings.domain.*; import com.workworth.salary.application.MonthlySalaryRateService; import com.workworth.workday.application.WorkdayService; import java.math.*; import java.time.*; import org.springframework.stereotype.Service;
@Service public class ActiveEarningProjectionService {private final WorkdayService workdays;private final MonthlySalaryRateService rates;private final Clock clock;public ActiveEarningProjectionService(WorkdayService w,MonthlySalaryRateService r,Clock c){workdays=w;rates=r;clock=c;} public EarningProjection current(){LocalDate date=LocalDate.now(clock);try{var day=workdays.reconcile(date);long seconds=workdays.time(day);var rate=rates.getRate(YearMonth.from(date));return new EarningProjection(date,EarningStatus.AVAILABLE,seconds,rate.hourlyNetRate().multiply(BigDecimal.valueOf(seconds)).divide(BigDecimal.valueOf(3600),12,RoundingMode.HALF_UP),rate.currencyCode());}catch(RuntimeException ex){return new EarningProjection(date,EarningStatus.UNAVAILABLE,0,null,null);}}}
